import React from "react";
import { Route, Routes, Navigate } from "react-router-dom";
import DashboardPage from "../pages/dashboard/DashboardPage";
import TemplateNewPage from "../pages/templates/TemplateNewPage";
import TemplateShowPage from "../pages/templates/TemplateShowPage";
import TemplateEditPage from "../pages/templates/TemplateEditPage";
import TemplatesIndexPage from "../pages/templates/TemplatesIndexPage";
import SubmitterSignPage from "../pages/submitters/SubmitterSignPage";
import SubmissionShowPage from "../pages/submissions/SubmissionShowPage";
import SubmissionNewPage from "../pages/submissions/SubmissionNewPage";

const AppRoutes = () => {
  const routes = [
    {
      path: "/",
      component: <DashboardPage />,
      key: "home_page",
    },
    {
      path: "/templates",
      component: <TemplatesIndexPage />,
      key: "templates_index_page",
    },
    {
      path: "/templates/:id/edit",
      component: <TemplateEditPage />,
      key: "template_edit_page",
    },
    {
      path: "/templates/:id",
      component: <TemplateShowPage />,
      key: "templates_show_page",
    },
    {
      path: "/templates/new",
      component: <TemplateNewPage />,
      key: "template_new_page",
    },
    {
      path: "/templates/:id/submissions/new",
      component: <SubmissionNewPage />,
      key: "submission_new_page",
    },
    {
      path: "/sign/:slug",
      component: <SubmitterSignPage />,
      key: "submitter_sign_page",
    },
    {
      path: "/submissions/:id",
      component: <SubmissionShowPage />,
      key: "submission_show_page",
    },
    {
      path: "*",
      component: <Navigate to="/" />,
      key: "undefined_page",
    },
  ];

  const routeComponents = routes.map((item) => {
    return (
      <Route
        exact="true"
        path={item.path}
        element={item.component}
        key={item.key}
      />
    );
  });

  return <Routes>{routeComponents}</Routes>;
};

export default AppRoutes;

import React, { useState, useEffect } from "react";
import ReactDOMServer from 'react-dom/server';
import { useParams } from "react-router-dom";
import { DocusealForm } from "@docuseal/react";
import { PageLoader, LogoPlaceholder } from "../../ui";
import { v4 as uuidv4 } from 'uuid';

const SubmitterSignPage = () => {
  const { slug } = useParams();
  const [submitter, setSubmitter] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true);

    fetch(`/api/sign/${slug}`, {
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
    })
      .then((response) => response.json())
      .then((data) => {
        setSubmitter(data.submitter || {});
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error:", error);
        setLoading(true);
      });
  }, []);

  if (loading) {
    return <PageLoader />;
  } else if (submitter.slug) {
    return (
      <div
        className="bg-slate-50 rounded-box border border-slate-300"
        style={{ maxHeight: "calc(-90px + 100vh)", overflow: "auto" }}
      >
        <DocusealForm
          host={process.env.REACT_APP_DOCUSEAL_CDN_HOST}
          src={`${process.env.REACT_APP_DOCUSEAL_URL}/${submitter.id ? "s" : "d"}/${submitter.slug}`}
          rememberSignature={true}
          externalId={uuidv4()}
          email={submitter.email}
          logo={`data:image/svg+xml;base64,${btoa(ReactDOMServer.renderToString(<LogoPlaceholder />)).replace('\n', '')}`}
        />
      </div>
    );
  } else {
    return (
      <div className="hero py-12 bg-base-200">
        <div className="hero-content text-center">
          <div className="max-w-lg">
            <h1 className="text-5xl font-bold">Invalid Link</h1>
          </div>
        </div>
      </div>
    );
  }
};

export default SubmitterSignPage;

import React, { useState, useEffect } from "react";
import { DocusealBuilder } from "@docuseal/react";
import { useNavigate } from "react-router-dom";
import { useParams } from "react-router-dom";
import { PageLoader } from "../../ui";

const TemplateEditPage = () => {
  const { id: templateId } = useParams();
  const [token, setToken] = useState();
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    fetch(`/api/templates/${templateId}/edit`, {
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
    })
      .then((response) => response.json())
      .then((data) => {
        setToken(data.token);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error:", error);
        setLoading(false);
      });
  }, []);

  const handleTemplateSave = (data) => {
    fetch("/api/templates", {
      method: "PATCH",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: JSON.stringify({ template_id: templateId, external_id: data.id }),
    })
      .then((response) => response.json())
      .then((data) => {
        navigate(`/templates/${data.template.id}`);
      })
      .catch((error) => {
        console.error("Error:", error);
      });
  };

  const handleBuilderLoad = (data) => {
    for (const docusealBuilder of document.getElementsByTagName("docuseal-builder")) {
      const signYourselfButton = docusealBuilder.shadowRoot?.getElementById("sign_yourself_button");

      if (signYourselfButton) {
        signYourselfButton.addEventListener("click", (e) => {
          e.preventDefault();
          navigate(`/sign/${data.slug}`);
        });
      }
    }
  };

  if (loading) {
    return <PageLoader />;
  } else if (token) {
    return (
      <div
        key={Math.random()}
        className="bg-slate-50 rounded-box border border-slate-300 border-1 overflow-y-hidden"
      >
        <DocusealBuilder
          host={process.env.REACT_APP_DOCUSEAL_CDN_HOST}
          token={token}
          autosave={false}
          onSave={handleTemplateSave}
          onLoad={handleBuilderLoad}
          style={{ maxHeight: "calc(-90px + 100vh)", display: "block" }}
        />
      </div>
    );
  }
};

